message.content:
{
  "description": "The creature is shown in right-facing profile against a plain light background, standing on four stout limbs. It has an elongated, tapering snout with a dark nostril at the tip, a small dark eye, and a low, arched body almost entirely covered in overlapping large, rounded keratinous scales that are dark brown with tan edges and interspersed with patches of pale pink scales on the flanks, shoulder and mid-back. The head is small relative to the body, the tail is thick and tapering and extends to the left, and six prominent pink, feathery external gill stalks protrude from the sides and top of the head and neck behind the eye and ear region. The skin on the snout, lower neck and limbs is wrinkled and brownish-gray, and the feet bear curved claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and tapered to a blunt snout with a dark nostril at the very tip, small round black eye with a lower eyelid, fine whiskers around the muzzle, wrinkled tan-brown skin on the sides and underside, and small rounded scales covering the top of the head and snout",
      "where": "at the right end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "a small dark circular ear opening with a slightly raised rim, set in wrinkled skin just behind and slightly below the eye",
      "where": "on the side of the head behind the eye, at the base of the lower gill stalks"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, muscular limbs with wrinkled gray-brown skin on the lower portions and overlapping brown scales on the upper portions; the front legs are slightly bent forward and the hind legs are more upright",
      "where": "two forelegs under the chest and shoulder, two hind legs under the arched mid and rear body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad paws with thick textured pads and three to four visible curved, light-brown claws on each foot",
      "where": "at the ends of all four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick at the base and tapering toward the tip, completely covered in overlapping dark brown scales with tan edges, same texture as the body",
      "where": "extending to the left from the rear of the body, partially out of frame"
    },
    {
      "part": "gills",
      "looks_like": "six fleshy pink stalks each bearing many fine, feathery pink filaments along the sides; three stalks protrude from the side of the neck behind the ear and three smaller stalks protrude from the top of the head behind the scaled cap",
      "where": "clustered on the dorsal and lateral surfaces of the head and upper neck, behind the eye and ear"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded to teardrop-shaped keratinous scales with dark brown centers and lighter tan-brown edges, arranged in diagonal rows; smaller rounded scales cap the top of the head",
      "where": "covering the dorsal surface of the head, the entire back, sides, tail, and upper portions of all four limbs"
    },
    {
      "part": "plates",
      "looks_like": "same as scales - large overlapping plate-like scales forming an armor-like covering",
      "where": "over the back, sides, tail and upper limbs"
    },
    {
      "part": "markings",
      "looks_like": "irregular patches of pale pink scales with small darker speckles, contrasting with the surrounding dark brown scales",
      "where": "on the mid-back, lower flank, shoulder and foreleg region, interspersed among the brown scales"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin",
    "axolotl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
